<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('payments.manage');$pdo=Database::connection();$filter=(int)($_GET['invoice_id']??0);$where=$filter?'WHERE p.invoice_id = ?':'';$stmt=$pdo->prepare("SELECT p.*,i.invoice_number,i.currency,c.first_name,c.last_name,COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr WHERE pr.payment_id=p.payment_id AND pr.status='processed'),0) AS refunded FROM payments p JOIN invoices i ON i.invoice_id=p.invoice_id JOIN customers c ON c.customer_id=i.customer_id $where ORDER BY p.payment_date DESC LIMIT 250");$stmt->execute($filter?[$filter]:[]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Payments';$currentPage='payments';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><section class="ro-page-heading"><div><span class="ro-kicker">CASH RECEIPTS & RECONCILIATION</span><h1>Payments</h1><p>Review completed and failed payment records, transaction references and linked refunds.</p></div><div class="ro-heading-symbol"><i class="bi bi-credit-card-2-front"></i></div></section><section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">PAYMENT REGISTER</span><h2><?= $filter?'Payments for selected invoice':'All recorded payments' ?></h2></div><span class="ro-counter"><?= count($rows) ?> records</span></div><?php if(!$rows): ?><div class="ro-empty"><div class="ro-empty-icon"><i class="bi bi-credit-card"></i></div><strong>No payment records found</strong><p>Payments can be recorded from an issued invoice.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Receipt number</th><th>Invoice</th><th>Customer</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th><th>Refunded</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><strong><?= e($p['payment_number']) ?></strong></td><td><a class="ro-text-link" href="<?= e(base_url('admin/invoice-view.php?id='.(int)$p['invoice_id'])) ?>"><?= e($p['invoice_number']) ?></a></td><td><?= e($p['first_name'].' '.$p['last_name']) ?></td><td><?= e(ro_date($p['payment_date'])) ?></td><td><?= e(ucwords(str_replace('_',' ',$p['payment_method']))) ?></td><td><?= e($p['transaction_reference']?:'—') ?></td><td><?= ro_money($p['amount'],$p['currency']) ?></td><td><?= ro_money($p['refunded'],$p['currency']) ?></td><td><?= ro_status_badge($p['status']) ?></td><td><a class="btn btn-sm ro-btn-outline" href="<?= e(base_url('admin/payment-receipt.php?id='.(int)$p['payment_id'])) ?>">Receipt</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require BASE_PATH.'/includes/footer.php'; ?>
